// Isolated test: std.crypto.nacl.Box vs a real libsodium (PyNaCl) reference
// vector generated by gen_box_vector.py. This proves binary compatibility
// with the actual crypto stack the KeePassXC-Browser extension uses, not
// just Zig's internal self-consistency.

const std = @import("std");
const Box = std.crypto.nacl.Box;

const alice_pk = [_]u8{ 0xd2, 0xac, 0x15, 0x4d, 0x5d, 0xbe, 0x5d, 0x89, 0xf2, 0xc6, 0x87, 0x3c, 0xca, 0x12, 0xc4, 0x20, 0xa0, 0x95, 0xf2, 0x7a, 0x6d, 0x8e, 0x59, 0xaa, 0x00, 0x15, 0xb5, 0xac, 0x5a, 0xaf, 0x06, 0x5f };
const alice_sk = [_]u8{ 0xd6, 0xa0, 0xdb, 0x75, 0x79, 0xb4, 0x30, 0x80, 0x44, 0x73, 0x4b, 0x8d, 0x5f, 0x0a, 0x23, 0x8d, 0x8d, 0x29, 0x5f, 0x75, 0x23, 0xb6, 0xae, 0x74, 0xa4, 0x8f, 0x16, 0x5a, 0xad, 0x7f, 0x82, 0x3e };
const bob_pk = [_]u8{ 0x57, 0x31, 0xd5, 0x54, 0xef, 0x65, 0x65, 0xda, 0x6b, 0x07, 0xbe, 0x96, 0x4a, 0xb0, 0x59, 0xa2, 0x73, 0x73, 0xde, 0x39, 0xc7, 0xb0, 0x11, 0x58, 0x31, 0xeb, 0x7e, 0x95, 0x42, 0x33, 0x92, 0x77 };
const bob_sk = [_]u8{ 0x20, 0x1d, 0xbc, 0x61, 0x9f, 0xa6, 0x5b, 0xac, 0x4a, 0x04, 0xfa, 0x60, 0x6c, 0x93, 0xdb, 0x43, 0x25, 0x1b, 0xf3, 0xf1, 0x04, 0xc5, 0x0c, 0x9c, 0xf7, 0xe1, 0xae, 0x64, 0xfa, 0x7f, 0x7b, 0x56 };
const nonce = [_]u8{ 0xa5, 0x54, 0xa9, 0x46, 0x35, 0xa6, 0xa6, 0x89, 0xb5, 0x07, 0x41, 0x5b, 0xc3, 0x90, 0x60, 0x2f, 0x50, 0x0a, 0xa4, 0x95, 0xfc, 0x61, 0xe6, 0x23 };
const message = [_]u8{ 0x48, 0x65, 0x6c, 0x6c, 0x6f, 0x20, 0x4b, 0x65, 0x65, 0x50, 0x61, 0x73, 0x73, 0x48, 0x54, 0x54, 0x50, 0x32, 0x20, 0x66, 0x72, 0x6f, 0x6d, 0x20, 0x50, 0x79, 0x4e, 0x61, 0x43, 0x6c };
const ciphertext = [_]u8{ 0xe7, 0xd7, 0xbe, 0xd2, 0x88, 0x64, 0x2e, 0x0e, 0xf6, 0x0a, 0x96, 0x83, 0x75, 0x3c, 0xb9, 0xa6, 0x12, 0x7f, 0x7a, 0x0c, 0x93, 0x80, 0x1c, 0x74, 0x60, 0x35, 0x79, 0x02, 0x92, 0x70, 0xf6, 0x9c, 0xc9, 0x1c, 0xbb, 0x98, 0x68, 0x75, 0x1c, 0xa0, 0xb1, 0xfb, 0xf0, 0x5c, 0x02, 0x9f };

pub fn main() !void {
    // Alice (sender) seals for Bob (recipient): her secret key + his public key.
    var c: [message.len + Box.tag_length]u8 = undefined;
    try Box.seal(&c, &message, nonce, bob_pk, alice_sk);

    const seal_ok = std.mem.eql(u8, &c, &ciphertext);
    std.debug.print("SEAL vs PyNaCl ciphertext: {s}\n", .{if (seal_ok) "MATCH" else "MISMATCH"});
    if (!seal_ok) {
        std.debug.print("got:      {x}\n", .{c});
        std.debug.print("expected: {x}\n", .{ciphertext});
    }

    // Bob (recipient) opens using his secret key + Alice's public key.
    var m: [message.len]u8 = undefined;
    try Box.open(&m, &ciphertext, nonce, alice_pk, bob_sk);

    const open_ok = std.mem.eql(u8, &m, &message);
    std.debug.print("OPEN vs original message: {s}\n", .{if (open_ok) "MATCH" else "MISMATCH"});
    if (!open_ok) {
        std.debug.print("got:      \"{s}\"\n", .{m});
        std.debug.print("expected: \"{s}\"\n", .{message});
    }
}
